-- Additive migration: explicit capability grants (contract macguard.entitlements/1). Rows are never deleted; revocation sets revoked_at. Apply once, remote only with the owner's authorisation.
-- Tested by test/migrations.test.js on the frozen DEPLOYED schema (4d9b1ff) with data: upgrade equals schema.sql, data intact, 0001-0003 unchanged.
-- Rollback (owner, after exporting the grants: this drops them): DROP INDEX IF EXISTS entitlement_grants_subject; DROP TABLE IF EXISTS entitlement_grants;
-- Backward compatible: until it is applied the Worker reads no explicit grants (fail closed) and every other path works; apply it before granting anything.
CREATE TABLE IF NOT EXISTS entitlement_grants (id INTEGER PRIMARY KEY AUTOINCREMENT, subject_kind TEXT NOT NULL CHECK (subject_kind IN ('organization','user')), subject_id TEXT NOT NULL, capability TEXT NOT NULL CHECK (capability IN ('catalog.public.read','vulnerability.public.read','yara.community.download','rules.premium.read','rules.premium.download','ioc.premium.read','intel.correlation.read','intel.advanced.export','research.poc.metadata.read')), granted_at TEXT NOT NULL, expires_at TEXT, revoked_at TEXT, source TEXT NOT NULL CHECK (source IN ('manual','subscription')), reason TEXT NOT NULL, granted_by TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS entitlement_grants_subject ON entitlement_grants(subject_kind, subject_id);
